// Extract and validate input
const body = $input.item.json.body || $input.item.json;

const goal = body.goal;
const inputContext = body.input_context || {};
const maxRetries = body.max_retries || 7;
const enableCircuitBreaker = body.enable_circuit_breaker !== false;
const enableHealthChecks = body.enable_health_checks !== false;

// Generate session ID
const sessionId = `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Validate required fields
if (!goal) {
  throw new Error('Goal is required');
}

// Initialize workflow state
return {
  json: {
    sessionId,
    goal,
    inputContext,
    config: {
      maxRetries,
      enableCircuitBreaker,
      enableHealthChecks,
      initialDelay: 1.0,
      maxDelay: 60.0,
      backoffMultiplier: 2,
      apiUrl: body.api_url || 'http://localhost:8017/v1/generate',
      apiKey: body.api_key || 'sk-e0dde619-2dd3-4018-aad1-e7f602d58534'
    },
    circuitBreaker: {
      state: 'CLOSED',
      failureCount: 0,
      successCount: 0,
      lastFailureTime: null,
      threshold: 5,
      timeout: 60000
    },
    healthStatus: {
      isHealthy: true,
      apiSuccessRate: 1.0,
      totalApiCalls: 0,
      successfulApiCalls: 0
    },
    taskList: null,
    currentTaskIndex: 0,
    errors: [],
    startTime: new Date().toISOString()
  }
};

// Health Check Function
const state = $input.item.json;

if (!state.config.enableHealthChecks) {
  return {
    json: {
      ...state,
      healthStatus: {
        ...state.healthStatus,
        isHealthy: true,
        lastCheck: new Date().toISOString()
      }
    }
  };
}

const errors = [];
const now = Date.now();

// Check API success rate
let apiStatus = 'healthy';
if (state.healthStatus.apiSuccessRate < 0.5) {
  apiStatus = 'degraded';
  errors.push(`API success rate below 50%: ${(state.healthStatus.apiSuccessRate * 100).toFixed(1)}%`);
} else if (state.healthStatus.apiSuccessRate < 0.8) {
  apiStatus = 'warning';
}

// Check circuit breaker status
if (state.circuitBreaker.state === 'OPEN') {
  errors.push('Circuit breaker is OPEN');
}

const isHealthy = apiStatus !== 'degraded' && state.circuitBreaker.state !== 'OPEN';

return {
  json: {
    ...state,
    healthStatus: {
      ...state.healthStatus,
      isHealthy,
      apiStatus,
      lastCheck: new Date().toISOString(),
      errors
    }
  }
};

// Check Circuit Breaker State
const state = $input.item.json;

if (!state.config.enableCircuitBreaker) {
  return {
    json: {
      ...state,
      canProceed: true
    }
  };
}

const cb = state.circuitBreaker;
const now = Date.now();

if (cb.state === 'OPEN') {
  const timeSinceFailure = cb.lastFailureTime ? now - cb.lastFailureTime : 0;

  if (timeSinceFailure >= cb.timeout) {
    return {
      json: {
        ...state,
        circuitBreaker: {
          ...cb,
          state: 'HALF_OPEN',
          successCount: 0
        },
        canProceed: true
      }
    };
  } else {
    const waitTime = (cb.timeout - timeSinceFailure) / 1000;
    throw new Error(`Circuit breaker is OPEN. Wait ${waitTime.toFixed(1)}s before retry`);
  }
}

return {
  json: {
    ...state,
    canProceed: true
  }
};

// Create Task List Prompt
const state = $input.item.json;

const prompt = `Create a comprehensive task list for the following goal: "${state.goal}"

=== INPUT CONTEXT ===
${JSON.stringify(state.inputContext, null, 2)}

=== REQUIREMENTS ===
Each task should be:
- Specific and actionable
- Have clear input and output expectations
- Include error handling considerations
- Be executable and testable
- Include realistic time estimates
- Specify what files will be created, read, or modified

For each task, include a "file_operations" section specifying:
- What files will be created (with paths)
- What files will be read
- What files will be modified
- What files will be deleted (if any)

=== RESPONSE FORMAT ===
Return ONLY valid JSON in this exact format:
{
  "id": "generated_unique_id",
  "title": "Task List Title",
  "description": "Overall description",
  "tasks": [
    {
      "id": "task_1",
      "title": "Task Title",
      "description": "What this task accomplishes",
      "type": "conversion",
      "priority": "high",
      "dependencies": [],
      "estimated_time": 30,
      "file_operations": [
        {
          "operation": "create",
          "file_path": "./output/file.tsx",
          "description": "Description",
          "priority": "high"
        }
      ]
    }
  ],
  "goals": ["primary_goal"]
}

Task types: code_generation, analysis, conversion, review, testing, cleanup, maintenance, optimization
Priority levels: high, medium, low
File operations: create, read, delete, modify, execute`;

const systemInstruction = "You are an expert project manager and developer. Return ONLY valid JSON without markdown formatting. Include comprehensive file operation specifications for each task.";

return {
  json: {
    ...state,
    currentPrompt: prompt,
    currentSystemInstruction: systemInstruction,
    currentOperation: 'create_task_list',
    retryCount: 0
  }
};

// Update Circuit Breaker on API Success
const items = $input.all();
const stateItem = items[0];
const apiItem = items[1];

const state = stateItem.json;
const apiResponse = apiItem.json;

if (!state.config.enableCircuitBreaker) {
  return [{
    json: {
      ...state,
      apiResponse: apiResponse.output_text || JSON.stringify(apiResponse)
    }
  }];
}

const cb = state.circuitBreaker;

if (cb.state === 'HALF_OPEN') {
  cb.successCount++;
  if (cb.successCount >= 2) {
    cb.state = 'CLOSED';
    cb.failureCount = 0;
    cb.successCount = 0;
  }
} else if (cb.state === 'CLOSED') {
  cb.failureCount = Math.max(0, cb.failureCount - 1);
}

// Update health status
state.healthStatus.totalApiCalls++;
state.healthStatus.successfulApiCalls++;
state.healthStatus.apiSuccessRate = state.healthStatus.successfulApiCalls / state.healthStatus.totalApiCalls;

return [{
  json: {
    ...state,
    circuitBreaker: cb,
    apiResponse: apiResponse.output_text || JSON.stringify(apiResponse)
  }
}];

// Update Circuit Breaker on API Failure
const items = $input.all();
const stateItem = items[0];
const errorItem = items[1];

const state = stateItem.json;
const error = errorItem.json.error || 'Unknown API error';

if (!state.config.enableCircuitBreaker) {
  return [{
    json: {
      ...state,
      lastError: error
    }
  }];
}

const cb = state.circuitBreaker;
const now = Date.now();

cb.failureCount++;
cb.lastFailureTime = now;

if (cb.state === 'HALF_OPEN') {
  cb.state = 'OPEN';
  cb.successCount = 0;
} else if (cb.failureCount >= cb.threshold) {
  cb.state = 'OPEN';
}

// Update health status
state.healthStatus.totalApiCalls++;
state.healthStatus.apiSuccessRate = state.healthStatus.successfulApiCalls / state.healthStatus.totalApiCalls;

state.errors.push({
  timestamp: new Date().toISOString(),
  operation: state.currentOperation,
  error: error,
  circuitBreakerState: cb.state
});

return [{
  json: {
    ...state,
    circuitBreaker: cb,
    lastError: error
  }
}];

// Parse and Validate Task List
const state = $input.item.json;
const apiResponse = state.apiResponse;

function extractJSON(text) {
  text = text.replace(/```(?:json|typescript|tsx|javascript)?\n?/g, '');
  text = text.replace(/```/g, '');

  const lines = text.split('\n');
  if (lines[0].trim().toLowerCase() === 'json') {
    text = lines.slice(1).join('\n');
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return text.substring(firstBrace, lastBrace + 1);
  }

  return text.trim();
}

function repairJSON(jsonStr) {
  jsonStr = jsonStr.replace(/,(\s*})/g, '$1');
  jsonStr = jsonStr.replace(/,(\s*])/g, '$1');
  return jsonStr;
}

try {
  let jsonText = extractJSON(apiResponse);
  jsonText = repairJSON(jsonText);

  const taskListData = JSON.parse(jsonText);

  if (!taskListData.id || !taskListData.title || !taskListData.tasks) {
    throw new Error('Invalid task list structure');
  }

  taskListData.tasks = taskListData.tasks.map((task, index) => ({
    ...task,
    status: 'pending',
    retryCount: 0,
    createdAt: new Date().toISOString(),
    index
  }));

  return {
    json: {
      ...state,
      taskList: taskListData,
      currentTaskIndex: 0,
      taskListCreated: true
    }
  };

} catch (error) {
  const fallbackTaskList = {
    id: `fallback_${Date.now()}`,
    title: 'Fallback Task List',
    description: 'Created due to JSON parsing failure',
    tasks: [
      {
        id: 'fallback_task_1',
        title: 'Manual Review Required',
        description: `JSON parsing failed: ${error.message}`,
        type: 'review',
        priority: 'high',
        status: 'pending',
        file_operations: [],
        index: 0
      }
    ],
    goals: [state.goal]
  };

  return {
    json: {
      ...state,
      taskList: fallbackTaskList,
      currentTaskIndex: 0,
      taskListCreated: true,
      errors: [...state.errors, {
        timestamp: new Date().toISOString(),
        operation: 'parse_task_list',
        error: error.message,
        usedFallback: true
      }]
    }
  };
}

// Get Next Task
const state = $input.item.json;
const tasks = state.taskList.tasks;
const currentIndex = state.currentTaskIndex;

if (currentIndex >= tasks.length) {
  return {
    json: {
      ...state,
      allTasksCompleted: true
    }
  };
}

const currentTask = tasks[currentIndex];

// Check dependencies
const completedTaskIds = tasks
  .filter(t => t.status === 'completed')
  .map(t => t.id);

const dependenciesSatisfied = !currentTask.dependencies || 
  currentTask.dependencies.every(depId => completedTaskIds.includes(depId));

if (!dependenciesSatisfied) {
  for (let i = currentIndex + 1; i < tasks.length; i++) {
    const task = tasks[i];
    const satisfied = !task.dependencies || 
      task.dependencies.every(depId => completedTaskIds.includes(depId));

    if (satisfied && task.status === 'pending') {
      return {
        json: {
          ...state,
          currentTask: task,
          currentTaskIndex: i
        }
      };
    }
  }

  return {
    json: {
      ...state,
      allTasksCompleted: true
    }
  };
}

return {
  json: {
    ...state,
    currentTask,
    currentTaskIndex: currentIndex
  }
};

// Prepare Task Execution
const state = $input.item.json;
const task = state.currentTask;

let prompt = '';

switch (task.type) {
  case 'code_generation':
    prompt = `Generate code for: ${task.description}\n\nInput: ${JSON.stringify(task.input_data || {}, null, 2)}\n\nRequirements:\n- Modern features\n- Error handling\n- Best practices\n- Return only code`;
    break;

  case 'conversion':
    prompt = `Convert: ${task.description}\n\nInput: ${JSON.stringify(task.input_data || {}, null, 2)}\n\nRequirements:\n- Best practices\n- Clean code\n- Return only converted content`;
    break;

  case 'analysis':
    prompt = `Analyze: ${task.description}\n\nInput: ${JSON.stringify(task.input_data || {}, null, 2)}\n\nProvide insights and recommendations`;
    break;

  case 'review':
    prompt = `Review: ${task.description}\n\nInput: ${JSON.stringify(task.input_data || {}, null, 2)}\n\nProvide feedback on quality and improvements`;
    break;

  default:
    prompt = `Complete task: ${task.description}\n\nProvide detailed response`;
}

const systemInstruction = `You are an expert ${task.type} specialist. Provide high-quality output.`;

task.status = 'in_progress';
task.startTime = new Date().toISOString();

return {
  json: {
    ...state,
    currentPrompt: prompt,
    currentSystemInstruction: systemInstruction,
    currentOperation: `execute_task_${task.id}`,
    retryCount: task.retryCount || 0
  }
};

// Handle Task Result
const items = $input.all();
const stateItem = items[0];
const apiItem = items[1];

const state = stateItem.json;
const apiResponse = apiItem.json;
const task = state.currentTask;

task.status = 'completed';
task.completedAt = new Date().toISOString();
task.output = {
  content: apiResponse.output_text || JSON.stringify(apiResponse),
  summary: `Task completed: ${task.title}`,
  createdAt: new Date().toISOString()
};

if (task.startTime) {
  const startTime = new Date(task.startTime).getTime();
  const endTime = Date.now();
  task.actualTime = endTime - startTime;
}

state.taskList.tasks[state.currentTaskIndex] = task;
state.currentTaskIndex++;

return [{
  json: state
}];

// Handle Task Failure
const items = $input.all();
const stateItem = items[0];
const errorItem = items[1];

const state = stateItem.json;
const task = state.currentTask;
const error = errorItem.json.error || 'Unknown error';

task.retryCount = (task.retryCount || 0) + 1;

if (task.retryCount > state.config.maxRetries) {
  task.status = 'failed';
  task.errors = task.errors || [];
  task.errors.push({
    timestamp: new Date().toISOString(),
    error: error,
    retryCount: task.retryCount
  });

  state.currentTaskIndex++;

  state.errors.push({
    timestamp: new Date().toISOString(),
    taskId: task.id,
    taskTitle: task.title,
    error: `Task failed after ${task.retryCount} retries`
  });
} else {
  task.status = 'pending';

  const delay = Math.min(
    state.config.initialDelay * Math.pow(state.config.backoffMultiplier, task.retryCount),
    state.config.maxDelay
  );

  task.nextRetryTime = Date.now() + (delay * 1000);
}

state.taskList.tasks[state.currentTaskIndex] = task;

return [{
  json: state
}];

// Generate Final Report
const state = $input.item.json;
const tasks = state.taskList.tasks;

const completedTasks = tasks.filter(t => t.status === 'completed');
const failedTasks = tasks.filter(t => t.status === 'failed');
const pendingTasks = tasks.filter(t => t.status === 'pending');

const report = {
  sessionId: state.sessionId,
  goal: state.goal,
  startTime: state.startTime,
  endTime: new Date().toISOString(),
  taskList: {
    id: state.taskList.id,
    title: state.taskList.title,
    description: state.taskList.description
  },
  statistics: {
    total: tasks.length,
    completed: completedTasks.length,
    failed: failedTasks.length,
    pending: pendingTasks.length,
    successRate: tasks.length > 0 ? (completedTasks.length / tasks.length * 100).toFixed(1) + '%' : '0%'
  },
  healthStatus: state.healthStatus,
  circuitBreaker: {
    finalState: state.circuitBreaker.state,
    totalFailures: state.circuitBreaker.failureCount
  },
  completedTasks: completedTasks.map(t => ({
    id: t.id,
    title: t.title,
    type: t.type,
    executionTime: t.actualTime,
    output: t.output
  })),
  failedTasks: failedTasks.map(t => ({
    id: t.id,
    title: t.title,
    type: t.type,
    errors: t.errors
  })),
  errors: state.errors,
  success: failedTasks.length === 0 && completedTasks.length > 0
};

return {
  json: report
};
